import 'dart:math';
import 'package:flame/game.dart';
import 'package:flame/components.dart';
import 'package:flutter/material.dart';
import 'weapon.dart';
enum CreatureType { griffin, drake, skyhawk, ironboar, venomtail }
class BattleGame extends FlameGame {
 BattleGame(this.weapon,this.onFinished);
 final WeaponTier weapon; final ValueChanged<bool> onFinished; final Vector2 movement=Vector2.zero(); bool attacking=false; late Arena arena; double elapsed=0;
 int get enemiesRemaining=>arena.fighters.where((f)=>!f.player&&f.hp>0).length;
 @override Future<void> onLoad() async { arena=Arena(this); world.add(arena); camera.viewfinder.zoom=1; camera.follow(arena.player,maxSpeed:900); }
 void move(Offset v){movement.setValues(v.dx,v.dy);if(movement.length>1)movement.normalize();}
}
class Arena extends Component with HasGameReference<BattleGame> {
 final List<Fighter> fighters=[]; late Fighter player; bool ended=false;
 @override Future<void> onLoad() async { player=Fighter(true,game.weapon.damage,game.weapon.reach,game.weapon.cooldown,18,120,220,const Color(0xFFD97706))..position=Vector2(1200,1200);fighters.add(player);final stats=<List<dynamic>>[[70,160,14,65,.7,20,0xFFC2410C],[55,130,16,220,1.4,22,0xFF166534],[45,220,12,55,.5,16,0xFF92400E],[120,110,20,60,1.1,26,0xFF44403C],[60,150,10,70,.8,18,0xFF4D7C0F]];for(var i=0;i<14;i++){final s=stats[i%5];final a=i*pi*2/14;final r=260+(i%4)*70;final f=Fighter(false,(s[0] as num).toDouble(),(s[1] as num).toDouble(),(s[4] as num).toDouble(),(s[5] as num).toDouble(),(s[2] as num).toDouble(),(s[3] as num).toDouble(),Color(s[6] as int))..position=Vector2(1200+cos(a)*r,1200+sin(a)*r);fighters.add(f);}addAll(fighters); }
 @override void update(double dt){super.update(dt);if(ended)return;game.elapsed+=dt;final alive=fighters.where((f)=>f.hp>0).toList();if(player.hp<=0){ended=true;game.onFinished(false);return;}if(alive.where((f)=>!f.player).isEmpty){ended=true;game.onFinished(true);return;}for(final f in alive){f.cooldown=max(0,f.cooldown-dt);f.flash=max(0,f.flash-dt);if(f.player){f.velocity=game.movement.clone();if(game.attacking)f.attack();}else{Fighter? nearest;var best=double.infinity;for(final e in alive){if(e==f)continue;final d=f.position.distanceTo(e.position);if(d<best){best=d;nearest=e;}}if(nearest!=null){final d=nearest.position-f.position;f.facing=atan2(d.y,d.x);if(best>f.range)f.velocity=d.normalized();else if(best<f.radius+nearest.radius+8)f.velocity=-d.normalized()*.4;else{f.velocity=Vector2(-sin(f.facing),cos(f.facing))*.25;if(f.cooldown<=0)f.attack();}}}if(f.velocity.length2>1)f.velocity.normalize();f.position+=f.velocity*f.speed*dt;f.position.x=f.position.x.clamp(20,2380);f.position.y=f.position.y.clamp(20,2380);}for(var i=0;i<alive.length;i++){for(var j=i+1;j<alive.length;j++){final a=alive[i],b=alive[j],d=b.position-a.position,dist=d.length,need=a.radius+b.radius;if(dist>0&&dist<need){final push=d.normalized()*((need-dist)*.5);a.position-=push;b.position+=push;}}}}
}
class Fighter extends PositionComponent with HasGameReference<BattleGame>{Fighter(this.player,this.maxHp,this.range,this.interval,this.radius,this.hp,this.speed,this.color);final bool player;final double maxHp,range,interval,radius,speed;final Color color;double hp,cooldown=0,flash=0,facing=0;Vector2 velocity=Vector2.zero();void attack(){if(cooldown>0||hp<=0)return;cooldown=interval;final targets=game.arena.fighters.where((f)=>f!=this&&f.hp>0).toList()..sort((a,b)=>position.distanceTo(a.position).compareTo(position.distanceTo(b.position)));var hits=0;for(final t in targets){final d=t.position-position;if(d.length>range+t.radius)continue;var delta=(atan2(d.y,d.x)-facing)%(2*pi);if(delta>pi)delta-=2*pi;if(delta< -pi)delta+=2*pi;if(delta.abs()>pi*.85/2)continue;t.hp=max(0,t.hp-(player?game.weapon.damage:(maxHp>100?20:14)));t.flash=.16;hits++;if(player&&game.weapon==WeaponTier.storm){for(final n in targets){if(n!=t&&n.position.distanceTo(t.position)<60)n.hp=max(0,n.hp-15);}}if(hits>=(player&&game.weapon==WeaponTier.trident?2:1))break;}}
 @override void render(Canvas c){super.render(c);if(hp<=0){c.drawCircle(Offset.zero,radius*.7,Paint()..color=const Color(0x553B352C));return;}c.save();c.rotate(facing);c.drawOval(Rect.fromCenter(center:Offset(0,radius*.6),width:radius*2,height:radius*.7),Paint()..color=const Color(0x26000000));c.drawCircle(Offset.zero,radius,Paint()..color=flash>0?const Color(0xFFFFF3D8):color);c.drawLine(Offset(radius*.2,0),Offset(radius+14,0),Paint()..color=const Color(0xFFE7D8B8)..strokeWidth=player?5:2.5);c.restore();if(hp<maxHp){c.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(-radius,-radius-8,radius*2,4),const Radius.circular(3)),Paint()..color=const Color(0xFFDED8CC));c.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(-radius,-radius-8,radius*2*hp/maxHp,4),const Radius.circular(3)),Paint()..color=const Color(0xFF15803D));}}
}
